import { clsx, type ClassValue } from "clsx";
import { extendTailwindMerge } from "tailwind-merge";

const twMerge = extendTailwindMerge({
  extend: { theme: { radius: ["control", "surface", "overlay"], shadow: ["overlay"] } },
});

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import { useId, useState, type KeyboardEvent } from "react";
import { cn } from "./lib/cn";
import "./rating.css";

const STAR = "M12 2.6l2.83 5.9 6.47.84-4.74 4.5 1.2 6.43L12 17.17l-5.76 3.1 1.2-6.43-4.74-4.5 6.47-.84z";

function Star({ fill }: { fill: "full" | "half" | "empty" }) {
  return (
    <span data-slot="rating-glyph" data-fill={fill} aria-hidden="true">
      <svg viewBox="0 0 24 24" data-layer="track"><path d={STAR} /></svg>
      <svg viewBox="0 0 24 24" data-layer="fill"><path d={STAR} /></svg>
    </span>
  );
}

const fillOf = (shown: number, index: number) => (shown >= index ? "full" : shown >= index - 0.5 ? "half" : "empty");
const roundHalf = (value: number) => Math.round(value * 2) / 2;
const formatValue = (value: number) => (Number.isInteger(value) ? String(value) : value.toFixed(1));

export type RatingProps = {
  /** Names the group, e.g. "Rate this recipe". Shown as the legend unless `hideLabel`. */
  label: string;
  hideLabel?: boolean;
  value?: number;
  defaultValue?: number;
  onValueChange?: (value: number) => void;
  /** Number of stars. */
  max?: number;
  /** 0.5 allows half stars. */
  step?: 1 | 0.5;
  /** Submitted with the form. */
  name?: string;
  disabled?: boolean;
  /** Display only: one image with the value in words, e.g. a product's average. */
  readOnly?: boolean;
  /** A word for each whole star, shown beside the stars, e.g. ["Poor", "Fair", "Good", "Great", "Loved it"]. */
  labels?: readonly string[];
  /** Choosing the current value again, or Delete, clears it. */
  clearable?: boolean;
  /** Read-only: how many ratings the average comes from. */
  count?: number;
  /** Read-only: show the number after the stars. */
  showValue?: boolean;
  size?: "sm" | "md" | "lg";
  className?: string;
};

/**
 * Stars that work as a native radio group: arrows change the value, the
 * chosen star settles in, a pointer previews before you choose, and the
 * value posts with the form. Read-only, it is one image that says the
 * average and how many ratings it comes from.
 */
export function Rating({
  label,
  hideLabel = false,
  value: controlled,
  defaultValue = 0,
  onValueChange,
  max = 5,
  step = 1,
  name,
  disabled,
  readOnly = false,
  labels,
  clearable = true,
  count,
  showValue = true,
  size = "md",
  className,
}: RatingProps) {
  const groupName = useId();
  const [inner, setInner] = useState(defaultValue);
  const [hover, setHover] = useState<number | null>(null);
  const [pop, setPop] = useState({ star: 0, n: 0 });
  const value = controlled ?? inner;
  const stars = Array.from({ length: max }, (_, i) => i + 1);
  const wordFor = (v: number) => (labels && v > 0 ? labels[Math.min(labels.length, Math.ceil(v)) - 1] : undefined);

  if (readOnly) {
    const shown = roundHalf(value);
    const spoken = `Rated ${formatValue(Math.round(value * 10) / 10)} out of ${max}${count !== undefined ? `, from ${count.toLocaleString("en-US")} ratings` : ""}`;
    return (
      <span data-slot="rating" data-readonly="" data-size={size} role="img" aria-label={spoken} className={cn("inline-flex items-center gap-1.5", className)}>
        <span data-slot="rating-stars" aria-hidden="true">
          {stars.map((star) => (
            <span key={star} data-slot="rating-star">
              <Star fill={fillOf(shown, star)} />
            </span>
          ))}
        </span>
        {showValue && <span data-slot="rating-value" aria-hidden="true">{formatValue(Math.round(value * 10) / 10)}</span>}
        {count !== undefined && <span data-slot="rating-count" aria-hidden="true">({count.toLocaleString("en-US")})</span>}
      </span>
    );
  }

  function choose(next: number, star: number) {
    const resolved = clearable && next === value ? 0 : next;
    if (controlled === undefined) setInner(resolved);
    onValueChange?.(resolved);
    if (resolved) setPop((current) => ({ star, n: current.n + 1 }));
  }

  function clear(event: KeyboardEvent) {
    if (!clearable || (event.key !== "Backspace" && event.key !== "Delete")) return;
    event.preventDefault();
    if (controlled === undefined) setInner(0);
    onValueChange?.(0);
  }

  const shown = hover ?? value;
  const word = wordFor(shown);
  const options = (star: number) => (step === 0.5 ? [star - 0.5, star] : [star]);

  return (
    <fieldset data-slot="rating" data-size={size} disabled={disabled} className={cn("m-0 min-w-0 border-0 p-0", className)}>
      <legend className={cn("mb-1.5 p-0 text-sm font-medium", hideLabel && "sr-only")}>{label}</legend>
      <div className="flex flex-wrap items-center gap-x-3 gap-y-1">
        <div data-slot="rating-stars" onPointerLeave={() => setHover(null)}>
          {stars.map((star) => (
            <span key={star} data-slot="rating-star" data-half={step === 0.5 || undefined}>
              <span key={pop.star === star ? pop.n : 0} data-slot="rating-settle" data-pop={pop.star === star && pop.n > 0 ? "" : undefined}>
                <Star fill={fillOf(shown, star)} />
              </span>
              {options(star).map((option) => (
                <input
                  key={option}
                  type="radio"
                  name={name ?? groupName}
                  value={option}
                  checked={value === option}
                  data-side={step === 0.5 ? (option === star ? "end" : "start") : undefined}
                  aria-label={`${formatValue(option)} of ${max} stars${wordFor(option) ? `, ${wordFor(option)}` : ""}`}
                  onChange={() => choose(option, star)}
                  onClick={(event) => {
                    // A click on the already chosen star fires no change event: clear it here.
                    if (value === option && event.detail > 0) choose(option, star);
                  }}
                  onKeyDown={clear}
                  onPointerEnter={(event) => event.pointerType === "mouse" && setHover(option)}
                />
              ))}
            </span>
          ))}
        </div>
        {/* Each radio already says its word; this line is for the eye, and previews under the pointer. */}
        <span data-slot="rating-word" data-preview={hover !== null || undefined} aria-hidden="true">
          {word ?? (value > 0 ? `${formatValue(value)} of ${max}` : "Not rated")}
        </span>
      </div>
    </fieldset>
  );
}

/* rating.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Rating: stars in ember; a half star clips its fill at the middle. */
  [data-slot="rating"] { --star: 22px; --star-cell: 30px; }
  [data-slot="rating"][data-size="sm"] { --star: 15px; --star-cell: 20px; }
  [data-slot="rating"][data-size="lg"] { --star: 30px; --star-cell: 38px; }
  @media (pointer: coarse) { [data-slot="rating"]:not([data-readonly]) { --star-cell: 44px; } }
  [data-slot="rating"][data-readonly] { --star-cell: var(--star); }
  [data-slot="rating-stars"] { display: inline-flex; align-items: center; }
  [data-slot="rating-star"] { position: relative; display: grid; place-items: center; width: var(--star-cell); height: var(--star-cell); border-radius: var(--radius-control); }
  [data-slot="rating"][data-readonly] [data-slot="rating-star"] { width: calc(var(--star) + 2px); height: var(--star); }
  [data-slot="rating-star"]:has(input:focus-visible) { outline: 2px solid var(--ring); outline-offset: 0; }
  [data-slot="rating-star"] input {
    position: absolute; inset: 0; z-index: 1; margin: 0; opacity: 0; cursor: pointer; appearance: none;
  }
  [data-slot="rating-star"][data-half] input[data-side="start"] { inset-inline-end: 50%; }
  [data-slot="rating-star"][data-half] input[data-side="end"] { inset-inline-start: 50%; }
  [data-slot="rating"]:disabled input { cursor: not-allowed; }
  [data-slot="rating"]:disabled [data-slot="rating-stars"] { opacity: 0.45; }
  [data-slot="rating-settle"] { display: grid; }
  [data-slot="rating-settle"][data-pop] { animation: caliper-star-settle var(--duration-deliberate) var(--ease-settle); }
  [data-slot="rating-glyph"] { position: relative; display: grid; width: var(--star); height: var(--star); }
  [data-slot="rating-glyph"] svg { grid-area: 1 / 1; width: 100%; height: 100%; }
  [data-slot="rating-glyph"] [data-layer="track"] path { fill: var(--muted); stroke: var(--border-strong); stroke-width: 1.25; stroke-linejoin: round; }
  [data-slot="rating-glyph"] [data-layer="fill"] path { fill: var(--brand); stroke: var(--brand); stroke-width: 1.25; stroke-linejoin: round; }
  [data-slot="rating-glyph"] [data-layer="fill"] { clip-path: inset(0 100% 0 0); transition: clip-path var(--duration-fast) var(--ease-out); }
  [data-slot="rating-glyph"][data-fill="full"] [data-layer="fill"] { clip-path: inset(0 0 0 0); }
  [data-slot="rating-glyph"][data-fill="half"] [data-layer="fill"] { clip-path: inset(0 50% 0 0); }
  [dir="rtl"] [data-slot="rating-glyph"][data-fill="half"] [data-layer="fill"] { clip-path: inset(0 0 0 50%); }
  [data-slot="rating-word"] { min-width: 6ch; font-size: 13px; color: var(--muted-foreground); font-variant-numeric: tabular-nums; }
  [data-slot="rating-word"][data-preview] { color: var(--foreground); }
  [data-slot="rating-value"] { font-size: 13px; font-weight: 600; font-variant-numeric: tabular-nums; }
  [data-slot="rating-count"] { font-size: 13px; color: var(--muted-foreground); font-variant-numeric: tabular-nums; }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="rating-settle"][data-pop] { animation: none !important; }
  }
}

@keyframes caliper-star-settle { 0% { scale: 0.82; } 100% { scale: 1; } }
